"use client";
/* eslint-disable @next/next/no-html-link-for-pages, @next/next/no-location-assign-relative-destination -- A full document navigation intentionally exits the demo and reinitializes the identity boundary. */

import { useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { ArrowDownLeft, ArrowUpRight, BookOpen, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardList, Download, ExternalLink, Leaf, LayoutDashboard, ListFilter, LogOut, Plus, Settings, ShieldCheck, Sparkles, Sprout, Target, Trash2, TrendingUp, Wallet, X, Pencil, Archive, RotateCcw, Search, Info } from "lucide-react";
import { CATEGORIES, type FinanceState, type Goal } from "@/lib/types";
import { currentMonth, formatMoney, monthMetrics, goalProgress, savingSuggestions, estimateSaving, parseMoney, simulate, todayISO } from "@/lib/finance";
import { EDUCATION, answerEducation } from "@/lib/education";
import { uid, useFinance } from "@/lib/client-store";
import { useFinanceTools } from "@/lib/webmcp";
import { FinanceDialog, Field, type DialogSpec } from "./finance-dialog";

const NAV = [ { id: "overview", label: "Visão geral", icon: LayoutDashboard }, { id: "transactions", label: "Lançamentos", icon: ClipboardList }, { id: "savings", label: "Economizar", icon: Sprout }, { id: "goals", label: "Metas", icon: Target }, { id: "learn", label: "Aprender", icon: BookOpen } ] as const;
type View = typeof NAV[number]["id"] | "settings";
const category = (id: string) => CATEGORIES.find(c => c.id === id) ?? CATEGORIES[CATEGORIES.length - 1];
const dateLabel = (date: string) => date.split("-").reverse().join("/");
const monthLabel = (month: string) => new Date(`${month}-15T12:00:00`).toLocaleDateString("pt-BR", { month: "long", year: "numeric" });
const join = (...parts: (string | false | undefined)[]) => parts.filter(Boolean).join(" ");
const LOGIN = "/signin-with-chatgpt?return_to=" + encodeURIComponent("/?mode=account");

function Brand({ small = false }: { small?: boolean }) {
  return <span className={join("brand", small && "small")}><span className="brand-mark"><Sprout size={small ? 19 : 24} strokeWidth={1.8} /></span><span>IA<span className="brand-light">Financeira</span><small>MAIS CLAREZA. MAIS POSSIBILIDADES.</small></span></span>;
}

function Landing({ startDemo }: { startDemo: () => void }) {
  return <div className="landing">
    <header className="landing-nav"><a href="/" aria-label="IA Financeira, início"><Brand /></a><div className="landing-nav-actions"><a href="#como-funciona" className="text-link">Como funciona</a><a href={LOGIN} target="_top" className="button secondary">Entrar</a></div></header>
    <main>
      <section className="landing-hero">
        <div className="hero-copy"><span className="pill"><span className="dot" /> UM PASSO POSSÍVEL, TODOS OS DIAS</span><h1>Entenda seu dinheiro<br /><em>e comece a guardar<br className="desktop-break" /> para o que importa.</em></h1><p>Seu orçamento, seus compromissos e seus planos no mesmo lugar. Para cuidar do presente e construir o futuro no seu ritmo.</p><div className="hero-actions"><a href={LOGIN} target="_top" className="button primary large">Começar</a><button onClick={startDemo} className="button secondary large">Explorar demonstração</button></div><div className="hero-note"><ShieldCheck size={17} /><span>Sem conectar seu banco. Você está no controle.</span></div></div>
        <div className="hero-visual" aria-label="Exemplo ilustrativo de organização financeira"><div className="visual-orbit orbit-one" /><div className="visual-orbit orbit-two" /><div className="sample-card"><div className="sample-head"><span className="eyebrow">UM MÊS MAIS CLARO</span><span className="sample-dot" /></div><p className="muted">Resultado do mês</p><strong className="sample-number">R$ 300<span>,00</span></strong><div className="sample-chart"><div><span>Entrou</span><i style={{ width: "100%" }} /><b>R$ 3.000</b></div><div><span>Saiu</span><i style={{ width: "90%" }} /><b>R$ 2.700</b></div></div><div className="sample-footer"><CheckCircle2 size={17} /> Cada valor tem uma história.</div></div><div className="sample-goal"><span className="icon-wash"><Sprout size={26} /></span><div><small>Sua reserva, um passo de cada vez</small><strong>O futuro começa no presente.</strong></div></div><span className="visual-caption">Valores fictícios para ilustrar a ferramenta.</span></div>
      </section>
      <section id="como-funciona" className="landing-how"><div className="section-intro"><span className="eyebrow">CUIDAR DO DINHEIRO PODE SER MAIS SIMPLES</span><h2>Clareza para decidir.<br />Espaço para planejar.</h2></div><div className="feature-grid">{[{ icon: Wallet, title: "Entenda seu mês", text: "Veja o que entrou, o que saiu e quais contas ainda precisam da sua atenção." }, { icon: Sprout, title: "Encontre possibilidades", text: "Explore cenários de economia que fazem sentido para a sua realidade." }, { icon: Target, title: "Dê um nome ao futuro", text: "Organize metas, acompanhe sua reserva e celebre cada passo possível." }].map((f, i) => <article key={f.title}><span className="feature-top"><f.icon size={25} strokeWidth={1.5} /><small>0{i + 1}</small></span><h3>{f.title}</h3><p>{f.text}</p></article>)}</div></section>
      <section className="landing-bottom"><div><span className="eyebrow">SEM PRECISAR SABER TUDO PARA COMEÇAR</span><h2>O primeiro passo é olhar.</h2><p>Explore com dados fictícios e conheça as ferramentas.</p></div><button className="button primary large" onClick={startDemo}>Conhecer a demonstração</button></section>
    </main><footer className="landing-footer"><Brand small /><span>Organização financeira e educação, no seu ritmo.</span><span>Não movimentamos dinheiro.</span></footer>
  </div>;
}

export default function FinanceApp() {
  const store = useFinance();
  const { state, mode, loading, pending, send } = store;
  useFinanceTools(state, !loading && (mode === "demo" || (mode === "account" && !store.error)));
  const [view, setView] = useState<View>("overview");
  const [month, setMonth] = useState(currentMonth());
  const [dialog, setDialog] = useState<DialogSpec | null>(null);
  const [toast, setToast] = useState("");
  const [tab, setTab] = useState("records");
  const [filterCategory, setFilterCategory] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [search, setSearch] = useState("");
  const [showCalculation, setShowCalculation] = useState(false);
  const [showArchived, setShowArchived] = useState(false);
  const [openedGoal, setOpenedGoal] = useState<string | null>(null);
  const [learnTab, setLearnTab] = useState("guide");
  const [question, setQuestion] = useState("Como posso organizar este mês?");
  const [askedQuestion, setAskedQuestion] = useState("Como posso organizar este mês?");
  const [remoteDiagnosis, setRemoteDiagnosis] = useState<(Omit<ReturnType<typeof answerEducation>, "mode"> & { mode: "rules" | "assisted"; providerFallback?: boolean }) | null>(null);
  const [diagnosisPending, setDiagnosisPending] = useState(false);
  const [diagnosisNotice, setDiagnosisNotice] = useState("");
  const diagnosisRequest = useRef(0);
  const [savingPercent, setSavingPercent] = useState<Record<string, number>>({});
  const [deleteConfirmation, setDeleteConfirmation] = useState("");
  const [appError, setAppError] = useState("");
  useEffect(() => {
    const id = new URLSearchParams(window.location.search).get("view");
    // eslint-disable-next-line react-hooks/set-state-in-effect -- Synchronize the initial browser URL only after hydration.
    if (NAV.some(n => n.id === id) || id === "settings") setView(id as View);
  }, []);
  useEffect(() => { if (!toast) return; const timeout = window.setTimeout(() => setToast(""), 4200); return () => window.clearTimeout(timeout); }, [toast]);
  const metrics = useMemo(() => monthMetrics(state, month), [state, month]);
  const suggestions = useMemo(() => savingSuggestions(state, month), [state, month]);
  const rulesDiagnosis = useMemo(() => answerEducation(state, month, askedQuestion), [state, month, askedQuestion]);
  const diagnosis = remoteDiagnosis ?? rulesDiagnosis;
  useEffect(() => {
    diagnosisRequest.current += 1;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- A new financial snapshot invalidates the asynchronous external explanation.
    setRemoteDiagnosis(null); setDiagnosisNotice(""); setDiagnosisPending(false);
  }, [state, month]);
  const activeGoals = state.goals.filter(g => !g.archived);
  const mainGoal = activeGoals.find(g => g.kind === "reserve") ?? activeGoals[0];
  const monthlyTransactions = state.transactions.filter(t => t.date.startsWith(month));
  const filteredTransactions = monthlyTransactions.filter(t => (!filterCategory || t.category === filterCategory) && (!filterStatus || t.status === filterStatus) && (!search || t.description.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR")))).sort((a, b) => b.date.localeCompare(a.date));
  const upcoming = monthlyTransactions.filter(t => t.status === "planned").sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4);
  const navigate = (next: View) => { setView(next); setAppError(""); window.history.replaceState({}, "", `/?mode=${mode}&view=${next}`); window.scrollTo({ top: 0, behavior: "instant" }); };
  async function save(type: string, payload: Record<string, unknown>, id = uid()) { const result = await send(type, payload, id); setToast("Tudo certo. Seus registros foram atualizados."); return result; }
  async function run(action: () => Promise<unknown>) { setAppError(""); try { await action(); } catch (e) { setAppError(e instanceof Error ? e.message : "Não foi possível concluir. Tente novamente."); } }
  async function ask(nextQuestion: string) {
    if (diagnosisPending) return;
    const requestId = ++diagnosisRequest.current;
    setQuestion(nextQuestion); setAskedQuestion(nextQuestion); setRemoteDiagnosis(null); setDiagnosisNotice("");
    if (mode !== "account") return;
    setDiagnosisPending(true);
    try {
      const response = await fetch("/api/diagnosis", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ month, question: nextQuestion }), signal: AbortSignal.timeout(18000) });
      const data = await response.json() as NonNullable<typeof remoteDiagnosis> & { error?: string };
      if (!response.ok) throw new Error(data.error || "O serviço de explicações está indisponível. A análise por regras continua funcionando.");
      if (requestId !== diagnosisRequest.current) return;
      setRemoteDiagnosis(data);
      if (data.providerFallback) setDiagnosisNotice("O provedor de IA não respondeu de forma válida. Exibimos a análise automática por regras.");
    } catch (e) { if (requestId === diagnosisRequest.current) setDiagnosisNotice(e instanceof Error ? e.message : "Não foi possível consultar o serviço. A análise por regras continua disponível."); }
    finally { if (requestId === diagnosisRequest.current) setDiagnosisPending(false); }
  }
  function confirmDelete(type: string, id: string, title: string) { setDialog({ kind: "confirm", title: `Excluir ${title}?`, description: "Este registro será removido e os totais serão recalculados. Essa ação não pode ser desfeita.", destructive: true, action: async () => { await save(type, { id }); } }); }
  function changeMonth(delta: number) { const [year, m] = month.split("-").map(Number); const date = new Date(year, m - 1 + delta, 15); setMonth(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`); }
  async function exportData() {
    const data = mode === "demo" ? { mode: "demo", exportedAt: new Date().toISOString(), state } : await fetch("/api/account", { credentials: "same-origin" }).then(async r => { if (!r.ok) throw new Error("Não foi possível exportar seus dados."); return r.json(); });
    const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
    const link = document.createElement("a"); link.href = url; link.download = `ia-financeira-${mode}-${todayISO()}.json`; link.click(); URL.revokeObjectURL(url); setToast("Exportação preparada.");
  }
  if (loading) return <main className="loading-screen"><Brand /><div className="loader" /><p>Preparando um olhar mais claro sobre seu dinheiro…</p></main>;
  if (mode === "landing") return <Landing startDemo={store.enterDemo} />;
  if (mode === "account" && store.error) return <main className="access-screen"><Brand /><h1>Vamos abrir seu espaço.</h1><p className="notice error" role="alert">{store.error}</p><p>A entrada e a recuperação de acesso são gerenciadas pelo ChatGPT. Os registros da demonstração ficam separados da sua conta.</p><div className="hero-actions"><a href={LOGIN} target="_top" className="button primary">Entrar com ChatGPT</a><button className="button secondary" onClick={store.enterDemo}>Explorar demonstração</button></div></main>;
  return <div className="app-shell">
    <aside className="sidebar"><a className="sidebar-brand" href="/"><Brand /></a><div className="workspace-label">MEU ESPAÇO</div><nav aria-label="Navegação principal">{NAV.map(n => <button key={n.id} className={join("nav-item", view === n.id && "active")} onClick={() => navigate(n.id)} aria-current={view === n.id ? "page" : undefined}><n.icon size={20} strokeWidth={1.65} /><span>{n.label}</span>{view === n.id && <span className="nav-active-dot" />}</button>)}</nav><div className="sidebar-grow" /><div className="sidebar-note"><Leaf size={20} /><p>O importante é dar<br /><strong>o próximo passo possível.</strong></p></div><button className={join("nav-item", view === "settings" && "active")} onClick={() => navigate("settings")}><Settings size={19} /> Configurações</button><div className="sidebar-user"><span className="avatar">{(state.profile.name || "V").slice(0, 1).toUpperCase()}</span><div><strong>{state.profile.name || "Seu espaço"}</strong><small>{mode === "demo" ? "Conta demonstração" : store.localPreview ? "Conta local de teste" : "Conta pessoal"}</small></div><button className="icon-button" aria-label="Editar perfil" onClick={() => setDialog({ kind: "profile" })}><Pencil size={16} /></button></div></aside>
    <div className="app-main"><header className="topbar"><span className="breadcrumb">Meu espaço <ChevronRight size={14} /> <strong>{NAV.find(n => n.id === view)?.label ?? "Configurações"}</strong></span><a href="/" className="mobile-brand"><Brand small /></a><div className="topbar-right"><span className="mode-tag"><span className="dot" />{mode === "demo" ? "Modo demonstração" : store.localPreview ? "Teste local" : "Seus registros"}</span><button className="icon-button mobile-settings" aria-label="Configurações" onClick={() => navigate("settings")}><Settings size={20} /></button><button className="button help-button" onClick={() => { navigate("learn"); setLearnTab("guide"); }}><CircleHelp size={17} /> Precisa de uma mão?</button></div></header>
    {mode === "demo" && <div className="demo-banner"><Info size={15} /><span>Você está explorando com dados fictícios. As alterações ficam neste navegador.</span><a href={LOGIN} target="_top">Criar meu espaço</a></div>}
    {mode === "account" && store.localPreview && <div className="demo-banner"><Info size={15} /><span>Ambiente local: identidade de teste. A autenticação real fica disponível na versão publicada.</span></div>}
    <main id="main-content" className="content">
      <div className="page-heading"><div><span className="eyebrow">{view === "overview" ? `BEM-VINDO${state.profile.name ? `, ${state.profile.name.split(" ")[0].toUpperCase()}` : " AO SEU ESPAÇO"}` : view === "savings" ? "UM PLANO QUE CABE NA SUA VIDA" : view === "goals" ? "DÊ UM NOME AO QUE IMPORTA" : view === "learn" ? "CONHECIMENTO PARA DECIDIR" : view === "settings" ? "VOCÊ NO CONTROLE" : "CADA REGISTRO CONTA"}</span><h1>{view === "overview" ? "Seu dinheiro, com mais clareza." : view === "transactions" ? "Organize o seu mês." : view === "savings" ? "Pequenos ajustes. Possibilidades reais." : view === "goals" ? "Um passo mais perto." : view === "learn" ? "Aprender também é cuidar." : "Seu espaço, suas escolhas."}</h1><p>{view === "overview" ? "Entenda onde você está para escolher seu próximo passo." : view === "transactions" ? "Entradas, saídas e compromissos, sem perder nada de vista." : view === "savings" ? "Cenários opcionais, sem pressão para guardar o que ainda não sobra." : view === "goals" ? "Acompanhe o que você já guardou e planeje no seu ritmo." : view === "learn" ? "Explicações simples, números conferíveis e fontes para ir além." : "Perfil, privacidade e seus dados em um só lugar."}</p></div>{view !== "settings" && view !== "learn" && <div className="month-control"><button className="icon-button" aria-label="Mês anterior" onClick={() => changeMonth(-1)}><ChevronLeft size={18} /></button><label><CalendarDays size={16} /><span>{monthLabel(month)}</span><input aria-label="Mês de referência" type="month" value={month} min="1900-01" max="2200-12" onChange={e => e.target.value && setMonth(e.target.value)} /></label><button className="icon-button" aria-label="Próximo mês" onClick={() => changeMonth(1)}><ChevronRight size={18} /></button></div>}</div>
      {(appError || store.error) && <div className="notice error" role="alert">{appError || store.error}<button className="icon-button" aria-label="Fechar aviso" onClick={() => { setAppError(""); store.setError(""); }}><X size={17} /></button></div>}
      {!state.profile.onboardingDone && <div className="onboarding-banner"><span className="icon-wash"><Leaf size={23} /></span><div><strong>Vamos começar pelo que você já sabe?</strong><p>Informe seu objetivo e estimativas. Você pode preencher depois.</p></div><button className="button primary" onClick={() => setDialog({ kind: "profile" })}>Configurar meu perfil</button><button className="text-link" disabled={pending} onClick={() => void run(() => save("profile.update", { onboardingDone: true }))}>Agora não</button></div>}
      {view === "overview" && <>
        <section className="overview-top"><div className="month-summary"><div className="card-heading"><span className="light-eyebrow">SEU MÊS EM NÚMEROS</span><span className="soft-light-pill">{metrics.incomplete ? "Visão parcial" : "Registros do mês"}</span></div><span className="summary-label">Resultado do mês</span><strong className={join("summary-number", metrics.result < 0 && "negative-light")}>{formatMoney(metrics.result)}</strong><p className="summary-description">Receitas recebidas menos despesas pagas.<br />Este valor não é seu saldo bancário.</p><div className="summary-split"><div><span><ArrowDownLeft size={16} /> Entradas recebidas</span><strong>{formatMoney(metrics.income)}</strong></div><div><span><ArrowUpRight size={16} /> Despesas pagas</span><strong>{formatMoney(metrics.expenses)}</strong></div></div><button className="summary-link" onClick={() => setShowCalculation(!showCalculation)}>{showCalculation ? "Ocultar" : "Ver"} memória de cálculo</button></div><div className="overview-side"><div className="card pending-card"><span className="icon-wash amber"><CalendarDays size={20} /></span><div><span className="muted">Compromissos pendentes</span><strong>{formatMoney(metrics.pendingExpenses)}</strong><small>Despesas previstas para este mês</small></div></div><div className="card saved-card"><div><span className="muted">Valor registrado nas metas</span><strong>{formatMoney(metrics.guarded)}</strong><small>Posição em {dateLabel(metrics.guardedAsOf)} · inclui arquivadas</small></div><span className="icon-wash"><Sprout size={23} /></span></div><button className="button primary add-launch" onClick={() => setDialog({ kind: "transaction" })}><Plus size={19} /> Adicionar lançamento</button></div></section>
        {showCalculation && <section className="card calculation"><h3>De onde vêm esses números?</h3><div className="calculation-grid"><p><span>Resultado realizado</span><strong>{formatMoney(metrics.income)} − {formatMoney(metrics.expenses)} = {formatMoney(metrics.result)}</strong></p><p><span>Projeção com pendências do mês</span><strong>{formatMoney(metrics.result)} + {formatMoney(metrics.pendingIncome)} − {formatMoney(metrics.pendingExpenses)} = {formatMoney(metrics.projection)}</strong></p></div><p className="fine-print">Receitas previstas: {formatMoney(metrics.pendingIncome)}. Metas são registros de reserva separados; seus aportes não alteram o resultado. A projeção não representa dinheiro livre para gastar.</p></section>}
        {metrics.incomplete && <div className="notice warning"><Info size={19} /><div><strong>Este retrato ainda está incompleto.</strong><p>Não há receita realizada neste mês. Isso não significa que sua renda foi zero.</p><button className="text-link" disabled={pending} onClick={() => void run(() => save("profile.update", { confirmedNoIncomeMonths: [...new Set([...state.profile.confirmedNoIncomeMonths, month])] }))}>Confirmar que não houve receita neste mês</button></div></div>}
        {metrics.result < 0 && <div className="notice error"><Info size={19} /><div><strong>As saídas registradas superam as entradas em {formatMoney(-metrics.result)}.</strong><p>Reveja os registros e os próximos compromissos antes de planejar novos aportes.</p></div></div>}
        <section className="overview-charts"><div className="card expenses-chart"><div className="card-heading"><h2>Para onde seu dinheiro foi</h2><span className="caption">Despesas pagas</span></div><CategoryChart state={state} month={month} /><button className="text-link card-bottom-link" onClick={() => navigate("transactions")}>Ver todos os lançamentos</button></div><div className="card goal-highlight"><div className="card-heading"><h2>O futuro tem um nome</h2><Target size={19} className="green-text" /></div>{mainGoal ? <GoalSummary state={state} goal={mainGoal} asOf={metrics.guardedAsOf} onMove={() => setDialog({ kind: "movement", goal: mainGoal })} /> : <div className="empty-state compact"><Sprout size={32} /><h3>Seu próximo passo começa aqui.</h3><p>Pode ser uma reserva, um curso ou um plano só seu.</p><button className="button secondary" onClick={() => setDialog({ kind: "goal" })}>Criar minha primeira meta <Plus size={16} /></button></div>}</div></section>
        <section className="overview-bottom"><div className="card"><div className="card-heading"><h2>Próximos compromissos</h2><button className="text-link" onClick={() => { navigate("transactions"); setFilterStatus("planned"); }}>Ver todos</button></div>{upcoming.length ? <div className="upcoming-list">{upcoming.map(t => <div key={t.id}><span className={join("date-tile", t.date < todayISO() && "late")}><strong>{t.date.slice(8)}</strong><small>{t.date < todayISO() ? "pendente" : t.type === "income" ? "receber" : "pagar"}</small></span><div className="upcoming-info"><strong>{t.description}</strong><small>{category(t.category).label}</small></div><span className="money">{formatMoney(t.amount)}</span><button className="icon-button" title="Confirmar efetivação" aria-label={`Confirmar ${t.description}`} onClick={() => setDialog({ kind: "realize", item: t })}><Check size={18} /></button></div>)}</div> : <Empty title="Nenhum compromisso previsto" text="Cadastre as contas que ainda vão vencer para enxergar o mês com antecedência." />}</div><div className="insight-card"><span className="eyebrow"><Sparkles size={16} /> UM OLHAR PARA O SEU MÊS</span><h2>O próximo passo pode ser simples.</h2><p>{diagnosis.insights[0]}</p>{diagnosis.insights[1] && <p>{diagnosis.insights[1]}</p>}<span className="analysis-label">Análise automática por regras</span><button className="text-link" onClick={() => navigate("savings")}>Explorar possibilidades</button></div></section>
        <Comparison income={metrics.income} expenses={metrics.expenses} />
      </>}
      {view === "transactions" && <>
        <div className="section-toolbar"><div className="tabs" role="tablist" aria-label="Organização do mês">{[{ id: "records", text: "Lançamentos" }, { id: "budget", text: "Orçamento" }, { id: "debts", text: "Dívidas" }].map(t => <button role="tab" aria-selected={tab === t.id} key={t.id} className={tab === t.id ? "selected" : ""} onClick={() => setTab(t.id)}>{t.text}</button>)}</div><button className="button primary" onClick={() => setDialog({ kind: tab === "records" ? "transaction" : tab === "budget" ? "budget" : "debt" })}><Plus size={17} />{tab === "records" ? "Adicionar lançamento" : tab === "budget" ? "Definir limite" : "Adicionar dívida"}</button></div>
        {tab === "records" && <section className="card records-card"><div className="filters"><label className="search-input"><Search size={17} /><input aria-label="Buscar lançamento" value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar descrição…" /></label><label className="filter-select"><ListFilter size={15} /><select aria-label="Filtrar por categoria" value={filterCategory} onChange={e => setFilterCategory(e.target.value)}><option value="">Todas as categorias</option>{CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}</select></label><select aria-label="Filtrar por situação" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}><option value="">Todas as situações</option><option value="realized">Realizados</option><option value="planned">Previstos</option></select></div>
          <div className="table-scroll"><table className="data-table transaction-table"><thead><tr><th>Descrição</th><th>Categoria</th><th>Data</th><th>Situação</th><th className="numeric">Valor</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{filteredTransactions.map(t => <tr key={t.id}><td><span className="transaction-name"><span className={join("transaction-icon", t.type === "income" && "income")}>{t.type === "income" ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}</span><span><strong>{t.description}</strong><small>{t.type === "income" ? "Receita" : t.expenseKind === "fixed" ? "Despesa fixa" : "Despesa variável"}</small></span></span></td><td>{category(t.category).label}</td><td>{dateLabel(t.date)}</td><td><span className={join("status-pill", t.status === "planned" && "planned")}>{t.status === "planned" ? "Previsto" : t.type === "income" ? "Recebido" : "Pago"}</span></td><td className={join("numeric money", t.type === "income" && "green-text")}>{t.type === "income" ? "+" : "−"} {formatMoney(t.amount)}</td><td><span className="row-actions">{t.status === "planned" && <button className="icon-button" aria-label={`Confirmar ${t.description}`} title="Confirmar efetivação" onClick={() => setDialog({ kind: "realize", item: t })}><Check size={17} /></button>}<button className="icon-button" aria-label={`Editar ${t.description}`} onClick={() => setDialog({ kind: "transaction", item: t })}><Pencil size={15} /></button><button className="icon-button" aria-label={`Excluir ${t.description}`} onClick={() => confirmDelete("transaction.delete", t.id, "lançamento")}><Trash2 size={15} /></button></span></td></tr>)}</tbody></table></div>{!filteredTransactions.length && <Empty title="Nada por aqui, por enquanto." text="Adicione uma entrada ou saída ou ajuste os filtros para encontrar seus registros." action={() => setDialog({ kind: "transaction" })} actionLabel="Adicionar primeiro lançamento" />}<div className="table-foot">{filteredTransactions.length} registro(s) · {monthLabel(month)}<span>Valores previstos não entram no resultado realizado.</span></div>
        </section>}
        {tab === "budget" && <><div className="notice"><Info size={17} />O restante realizado é limite − despesas pagas. As contas pendentes aparecem separadas.</div><div className="budget-grid">{state.budgets.filter(b => b.month === month).map(b => { const paid = metrics.categoryExpenses[b.category] ?? 0; const planned = metrics.categoryPending[b.category] ?? 0; return <article className="card budget-card" key={b.id}><div className="card-heading"><h2>{category(b.category).label}</h2><span className="row-actions"><button className="icon-button" aria-label={`Editar limite de ${category(b.category).label}`} onClick={() => setDialog({ kind: "budget", item: b })}><Pencil size={15} /></button><button className="icon-button" aria-label={`Excluir limite de ${category(b.category).label}`} onClick={() => confirmDelete("budget.delete", b.id, "limite")}><Trash2 size={15} /></button></span></div><div className="budget-total"><strong>{formatMoney(paid)}</strong><span>de {formatMoney(b.limit)}</span></div><Progress percent={b.limit ? paid / b.limit * 100 : paid ? 100 : 0} alert={paid > b.limit} /><dl className="number-list"><div><dt>Despesas pendentes</dt><dd>{formatMoney(planned)}</dd></div><div><dt>Restante realizado</dt><dd className={paid > b.limit ? "red-text" : ""}>{formatMoney(b.limit - paid)}</dd></div><div><dt>Restante após compromissos</dt><dd>{formatMoney(b.limit - paid - planned)}</dd></div></dl>{paid > b.limit && <p className="inline-alert">Limite ultrapassado em {formatMoney(paid - b.limit)} pelas despesas pagas.</p>}{paid <= b.limit && paid + planned > b.limit && <p className="inline-alert">Com as pendências, o limite será ultrapassado em {formatMoney(paid + planned - b.limit)}.</p>}</article>; })}</div>{!state.budgets.some(b => b.month === month) && <div className="card"><Empty title="Um plano começa com uma referência." text="Escolha uma categoria e defina um limite mensal que você possa revisar ao longo do mês." action={() => setDialog({ kind: "budget" })} actionLabel="Definir primeiro limite" /></div>}</>}
        {tab === "debts" && <><div className="notice"><Info size={18} /><span>Saldo devedor é separado do orçamento. Vincule uma parcela a uma despesa uma única vez e atualize o saldo conforme o credor.</span></div><div className="debt-total card"><span>Saldo devedor informado</span><strong>{formatMoney(state.debts.reduce((sum, d) => sum + d.balance, 0))}</strong><small>Não somado às despesas mensais</small></div><div className="budget-grid">{state.debts.map(d => { const linked = state.transactions.find(t => t.id === d.transactionId); return <article className="card" key={d.id}><div className="card-heading"><h2>{d.name}</h2><span className="row-actions"><button className="icon-button" aria-label={`Editar ${d.name}`} onClick={() => setDialog({ kind: "debt", item: d })}><Pencil size={15} /></button><button className="icon-button" aria-label={`Excluir ${d.name}`} onClick={() => confirmDelete("debt.delete", d.id, "dívida")}><Trash2 size={15} /></button></span></div><strong className="debt-balance">{formatMoney(d.balance)}</strong><dl className="number-list"><div><dt>Parcela informada</dt><dd>{d.installment === null ? "Não informada" : formatMoney(d.installment)}</dd></div><div><dt>Vencimento</dt><dd>{d.dueDate ? dateLabel(d.dueDate) : "Não informado"}</dd></div><div><dt>Juros</dt><dd>{d.interestUnit === "unknown" || d.interestRate === null ? "Não informados" : `${d.interestRate}% ${d.interestUnit === "monthly" ? "ao mês" : "ao ano"}`}</dd></div></dl><div className="linked-transaction"><ClipboardList size={16} /><span>{linked ? `${linked.description} · ${formatMoney(linked.amount)} · ${linked.status === "planned" ? "prevista" : "paga"}` : "Sem parcela vinculada ao orçamento"}</span></div></article>; })}</div>{!state.debts.length && <div className="card"><Empty title="Suas dívidas, com clareza." text="Se tiver dívidas, registre os valores e as condições que conhece. Esse cadastro é opcional." action={() => setDialog({ kind: "debt" })} actionLabel="Cadastrar dívida" /></div>}</>}
      </>}
      {view === "savings" && <>
        <div className="savings-intro"><span className="icon-wash"><Sprout size={29} /></span><div><h2>Economizar começa por entender.</h2><p>Você escolhe o que faz sentido. As estimativas abaixo não são dinheiro já economizado e não alteram seus lançamentos.</p></div></div>
        {metrics.result < 0 && <div className="notice error"><Info size={19} /><span>Há um déficit registrado de <strong>{formatMoney(-metrics.result)}</strong>. Primeiro, confira entradas e compromissos. Não existe obrigação de poupar neste momento.</span></div>}
        {metrics.incomplete && <div className="notice warning"><Info size={18} /><span>Diagnóstico parcial: registre receitas ou confirme que não houve renda no mês, na Visão geral.</span></div>}
        <div className="saving-grid">{suggestions.map((s, i) => { const percent = savingPercent[s.category] ?? s.reductionPercent; const estimated = estimateSaving(s.baseAmount, percent); const accepted = state.savingActions.find(a => a.month === month && a.category === s.category); return <article className="card saving-card" key={s.id}><span className="saving-number">0{i + 1}</span><span className="eyebrow">{category(s.category).label}</span><h2>{s.title}</h2><p>{s.reason}</p><div className="saving-base"><span>Valor de origem neste mês</span><strong>{formatMoney(s.baseAmount)}</strong></div><Field label={`Cenário de redução: ${percent}%`}><input type="range" min="0" max="100" step="1" value={percent} onChange={e => setSavingPercent(old => ({ ...old, [s.category]: Number(e.target.value) }))} /></Field><div className="saving-impact"><span>Economia hipotética</span><strong>{formatMoney(estimated)}</strong><small>{formatMoney(s.baseAmount)} × {percent}%</small></div><button className={join("button", accepted ? "secondary" : "primary")} disabled={pending} onClick={() => void run(() => save("savingAction.save", { id: accepted?.id ?? uid(), month, category: s.category, reductionPercent: percent, baseAmount: s.baseAmount, estimatedSaving: estimated }))}>{accepted ? "Atualizar cenário escolhido" : "Escolher este próximo passo"}{accepted && <Check size={16} />}</button></article>; })}</div>
        {!suggestions.length && <div className="card"><Empty title="Vamos olhar os registros primeiro." text="Não há despesas elegíveis suficientes para sugerir uma redução. Registre seus gastos ou considere uma meta adequada à sua realidade." action={() => setDialog({ kind: "transaction" })} actionLabel="Adicionar lançamento" /></div>}
        <section className="card"><div className="card-heading"><h2>Seus passos escolhidos</h2><span className="caption">Cenários em acompanhamento</span></div>{state.savingActions.filter(a => a.month === month).length ? state.savingActions.filter(a => a.month === month).map(a => <div className="chosen-action" key={a.id}><span className="icon-wash"><CheckCircle2 size={21} /></span><div><strong>Rever {category(a.category).label.toLowerCase()}</strong><p>{a.reductionPercent}% sobre {formatMoney(a.baseAmount)} registrados na escolha → {formatMoney(a.estimatedSaving)} de economia estimada.</p><small>Confira o gasto realizado no fim do período. Nenhuma despesa foi reduzida automaticamente.</small></div><button className="icon-button" aria-label={`Remover cenário de ${category(a.category).label}`} onClick={() => void run(() => save("savingAction.delete", { id: a.id }))} disabled={pending}><X size={18} /></button></div>) : <p className="muted">Escolha um cenário acima para acompanhá-lo por aqui. Sem pressa.</p>}</section>
        <div className="gentle-cta"><div><h2>Guardar pode começar pequeno.</h2><p>Defina um objetivo sem assumir que o resultado do mês está disponível.</p></div><button className="button secondary" onClick={() => setDialog({ kind: "goal" })}>Planejar uma meta <Target size={17} /></button></div>
      </>}
      {view === "goals" && <>
        <div className="section-toolbar"><div className="goal-total"><span>Registrado em {dateLabel(metrics.guardedAsOf)}</span><strong>{formatMoney(metrics.guarded)}</strong><small>Inclui saldos das metas arquivadas</small></div><button className="button primary" onClick={() => setDialog({ kind: "goal" })}><Plus size={18} /> Criar nova meta</button></div><div className="notice"><Info size={18} /><span>Os valores são registros informados por você, não saldos bancários verificados. Registrar uma movimentação não transfere dinheiro.</span></div><label className="checkbox show-archived"><input type="checkbox" checked={showArchived} onChange={e => setShowArchived(e.target.checked)} />Mostrar metas arquivadas</label>
        <div className="goals-grid">{state.goals.filter(g => showArchived || !g.archived).map(g => <article key={g.id} className={join("card goal-card", g.archived && "archived")}><div className="card-heading"><span className="icon-wash">{g.kind === "reserve" ? <ShieldCheck size={22} /> : <Target size={22} />}</span><span className="row-actions">{g.archived && <span className="status-pill">Arquivada</span>}<button className="icon-button" aria-label={`Editar meta ${g.name}`} onClick={() => setDialog({ kind: "goal", item: g })}><Pencil size={16} /></button><button className="icon-button" aria-label={`${g.archived ? "Reativar" : "Arquivar"} meta ${g.name}`} disabled={pending} onClick={() => void run(() => save("goal.archive", { id: g.id, archived: !g.archived }))}>{g.archived ? <RotateCcw size={16} /> : <Archive size={16} />}</button></span></div><GoalSummary state={state} goal={g} asOf={metrics.guardedAsOf} onMove={() => setDialog({ kind: "movement", goal: g })} /><button className="text-link history-toggle" onClick={() => setOpenedGoal(openedGoal === g.id ? null : g.id)}>{openedGoal === g.id ? "Ocultar" : "Ver"} histórico <ChevronDown size={15} /></button>{openedGoal === g.id && <div className="movement-history"><div><span><strong>Saldo inicial</strong><small>{dateLabel(g.initialDate)}</small></span><b>{formatMoney(g.initialAmount)}</b></div>{state.movements.filter(m => m.goalId === g.id).sort((a, b) => b.date.localeCompare(a.date)).map(m => <div key={m.id}><span><strong>{{ deposit: "Aporte", withdrawal: "Retirada", adjustment_in: "Ajuste positivo", adjustment_out: "Ajuste negativo" }[m.type]}</strong><small>{dateLabel(m.date)}{m.note ? ` · ${m.note}` : ""}</small></span><b>{m.type === "deposit" || m.type === "adjustment_in" ? "+" : "−"} {formatMoney(m.amount)}</b></div>)}</div>}</article>)}</div>{!state.goals.filter(g => showArchived || !g.archived).length && <div className="card"><Empty title="O que você quer construir?" text="Crie uma meta pessoal ou uma reserva de emergência. É possível começar sem ter nenhum valor guardado." action={() => setDialog({ kind: "goal" })} actionLabel="Criar primeira meta" /></div>}
      </>}
      {view === "learn" && <>
        <div className="tabs learn-tabs" role="tablist" aria-label="Aprender">{[{ id: "guide", text: "Guias para o dia a dia" }, { id: "analysis", text: "Entenda seu mês" }, { id: "simulator", text: "Simulador" }].map(t => <button key={t.id} role="tab" aria-selected={learnTab === t.id} className={learnTab === t.id ? "selected" : ""} onClick={() => setLearnTab(t.id)}>{t.text}</button>)}</div>
        {learnTab === "guide" && <div className="education-grid">{EDUCATION.map((item, i) => <article className="card education-card" key={item.id}><div className="education-top"><span className="eyebrow">{item.theme}</span><span>0{i + 1}</span></div><h2>{item.title}</h2><p>{item.summary}</p><details><summary>Ver um exemplo <ChevronDown size={15} /></summary><p>{item.example}</p></details><a href={item.url} target="_blank" rel="noopener noreferrer" className="source-link">{item.sourceTitle}<ExternalLink size={13} /></a><small className="caption">Consultado em {dateLabel(item.consultedAt)}</small></article>)}</div>}
        {learnTab === "analysis" && <section className="card diagnosis"><span className="pill"><Sparkles size={14} /> {diagnosis.mode === "assisted" ? "Conceitos organizados com IA" : "Análise automática por regras"}</span><h2>Vamos entender os seus registros.</h2><p className="muted">Referência: {monthLabel(month)}. Os valores vêm dos lançamentos; o conteúdo educativo vem da base revisada.</p><div className="suggested-questions">{["Para onde meu dinheiro está indo?", "Como posso organizar este mês?", "Como planejar minha reserva?"].map(q => <button className="button secondary" key={q} disabled={diagnosisPending} onClick={() => void ask(q)}>{q}</button>)}</div><form className="question-form" onSubmit={e => { e.preventDefault(); void ask(question); }}><label className="sr-only" htmlFor="financial-question">Sua pergunta</label><input id="financial-question" value={question} maxLength={500} onChange={e => setQuestion(e.target.value)} placeholder="Pergunte sobre orçamento, reserva, juros…" required /><button className="button primary" type="submit" disabled={diagnosisPending}>{diagnosisPending ? "Analisando…" : "Entender"}</button></form>{diagnosisNotice && <div className="notice warning" role="status">{diagnosisNotice}</div>}<div className="diagnosis-answer" aria-live="polite"><h3>Resumo do mês</h3><p>{diagnosis.summary}</p><h3>Pontos de atenção</h3><ul>{diagnosis.insights.map(i => <li key={i}>{i}</li>)}</ul><h3>Próximos passos possíveis</h3>{diagnosis.actions.length ? <ul>{diagnosis.actions.map(a => <li key={a}>{a}</li>)}</ul> : <p>Confira os compromissos e considere definir uma meta compatível com sua situação.</p>}<h3>Conceitos relacionados à sua pergunta</h3><p>{diagnosis.answer}</p><div className="diagnosis-sources">{diagnosis.sources.map(s => <a key={s.id} className="source-link" href={s.url} target="_blank" rel="noopener noreferrer">{s.sourceTitle}<ExternalLink size={13} /></a>)}</div></div><div className="notice"><Info size={17} />{diagnosis.mode === "assisted" ? "A IA organizou os conceitos da base revisada a partir de métricas agregadas autorizadas. Os cálculos e os textos exibidos foram verificados pelo sistema." : remoteDiagnosis?.providerFallback ? "O serviço externo não retornou uma explicação válida. Os cálculos e o diagnóstico por regras permanecem disponíveis." : "Análise automática por regras. Nenhuma chamada bem-sucedida a modelo de IA compõe esta explicação."}</div></section>}
        {learnTab === "simulator" && <Simulator />}
      </>}
      {view === "settings" && <div className="settings-grid"><section className="card"><div className="card-heading"><h2>Seu perfil</h2><button className="button secondary" onClick={() => setDialog({ kind: "profile" })}><Pencil size={15} /> Editar</button></div><dl className="number-list"><div><dt>Nome</dt><dd>{state.profile.name || "Não informado"}</dd></div><div><dt>Renda</dt><dd>{state.profile.incomeType === "fixed" ? "Fixa" : "Variável"}</dd></div><div><dt>Renda prevista</dt><dd>{state.profile.expectedIncome === null ? "Não informada" : formatMoney(state.profile.expectedIncome)}</dd></div><div><dt>Despesas essenciais estimadas</dt><dd>{state.profile.essentialExpenses === null ? "Não informadas" : formatMoney(state.profile.essentialExpenses)}</dd></div><div><dt>Objetivo</dt><dd>{state.profile.initialObjective || "Não informado"}</dd></div></dl><p className="fine-print">Valores de perfil são estimativas. Não substituem os lançamentos.</p></section><section className="card"><h2>Seus dados, suas escolhas</h2><p>Coletamos o perfil e os registros financeiros que você informa para calcular seu orçamento, acompanhar metas e explicar resultados.</p><p>{mode === "demo" ? "Nesta demonstração, os dados ficam somente no armazenamento local deste navegador. Não use informações sensíveis no modo de demonstração." : "Seus registros ficam no banco do aplicativo, vinculados à sua identidade de acesso. O ChatGPT gerencia a autenticação; a infraestrutura do site é hospedada pela Cloudflare."}</p><p>Os registros ficam armazenados até você os remover ou solicitar exclusão. A exportação contém seus registros em JSON.</p><div className="notice"><ShieldCheck size={18} /><span>Não conectamos bancos nem executamos transferências. A análise por regras não compartilha dados com IA. Com integração habilitada e sua autorização, somente métricas agregadas necessárias podem ser enviadas à OpenAI.</span></div><button className="button secondary" onClick={() => void run(exportData)}><Download size={17} /> Exportar meus dados</button></section><section className="card"><h2>Análises e compartilhamento</h2><p>A análise automática por regras usa cálculos do aplicativo e conteúdo educativo revisado. Se a integração externa estiver configurada, você pode autorizar a OpenAI a organizar os conceitos da explicação.</p><label className="checkbox"><input type="checkbox" checked={state.profile.aiConsent} disabled={pending} onChange={e => void run(() => save("profile.update", { aiConsent: e.target.checked }))} /><span>Autorizar o envio de métricas financeiras agregadas (entradas, saídas, resultado e pendências) à OpenAI para organizar explicações quando a integração estiver configurada. Nomes e descrições dos lançamentos não são enviados.</span></label><p className="fine-print">Você pode revogar esta preferência aqui. O envio só ocorre ao pedir uma explicação em uma conta autenticada, com a integração configurada. Sem autorização ou em caso de falha, o diagnóstico por regras continua disponível.</p></section><section className="card"><h2>{mode === "demo" ? "Gerenciar demonstração" : "Acesso e exclusão"}</h2>{mode === "demo" ? <><p>Reinicie os exemplos fictícios ou comece uma demonstração vazia. Essa ação substitui somente os dados locais deste modo.</p><div className="settings-actions"><button className="button secondary" onClick={() => setDialog({ kind: "confirm", title: "Reiniciar demonstração?", description: "Os registros locais serão substituídos pelos exemplos fictícios iniciais.", action: async () => { store.resetDemo(); setToast("Demonstração reiniciada."); } })}><RotateCcw size={16} /> Restaurar exemplos</button><button className="button secondary" onClick={() => setDialog({ kind: "confirm", title: "Começar demonstração vazia?", description: "Todos os registros da demonstração deste navegador serão removidos.", action: async () => { store.resetDemo(true); setToast("Demonstração vazia, pronta para começar."); } })}>Começar do zero</button><a href="/" className="text-link"><LogOut size={16} /> Sair da demonstração</a></div></> : <><p>Entrada e recuperação de acesso são gerenciadas pelo ChatGPT.</p><a className="button secondary" href="/signout-with-chatgpt?return_to=/" target="_top"><LogOut size={16} /> Sair da conta</a><div className="delete-zone"><h3>Excluir dados do aplicativo</h3><p>Remove seu perfil e todos os registros deste aplicativo. Não exclui sua conta ChatGPT.</p><Field label="Digite EXCLUIR para confirmar"><input value={deleteConfirmation} onChange={e => setDeleteConfirmation(e.target.value)} placeholder="EXCLUIR" /></Field><button className="button danger" disabled={deleteConfirmation !== "EXCLUIR" || pending} onClick={() => setDialog({ kind: "confirm", title: "Excluir todos os seus dados?", description: "Essa ação é definitiva. Exporte os registros antes se quiser manter uma cópia.", destructive: true, action: async () => { const r = await fetch("/api/account", { method: "DELETE", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ confirmation: "EXCLUIR" }) }); if (!r.ok) throw new Error("Não foi possível excluir os dados. Tente novamente."); window.location.assign("/"); } })}><Trash2 size={16} /> Excluir meus dados</button></div></>}</section></div>}
      <footer className="app-footer"><span><Leaf size={14} /> Um próximo passo possível, no seu ritmo.</span><span>Registros manuais · valores em reais</span></footer>
    </main></div>
    <nav className="mobile-nav" aria-label="Navegação móvel">{NAV.map(n => <button key={n.id} className={view === n.id ? "active" : ""} onClick={() => navigate(n.id)} aria-current={view === n.id ? "page" : undefined}><n.icon size={21} strokeWidth={1.8} /><span>{n.label}</span></button>)}</nav>
    {dialog && <FinanceDialog key={JSON.stringify([dialog.kind, "item" in dialog ? dialog.item?.id : "goal" in dialog ? dialog.goal.id : null])} spec={dialog} state={state} month={month} pending={pending} close={() => { if (!pending) setDialog(null); }} save={save} />}
    {toast && <div className="toast" role="status"><CheckCircle2 size={18} /><span>{toast}</span><button className="icon-button" aria-label="Fechar confirmação" onClick={() => setToast("")}><X size={15} /></button></div>}
  </div>;
}


function Empty({ title, text, action, actionLabel }: { title: string; text: string; action?: () => void; actionLabel?: string }) {
  return <div className="empty-state"><span className="icon-wash"><Leaf size={28} /></span><h3>{title}</h3><p>{text}</p>{action && <button className="button secondary" onClick={action}>{actionLabel}<Plus size={16} /></button>}</div>;
}
function Progress({ percent, alert = false }: { percent: number; alert?: boolean }) {
  return <div className={join("progress-track", alert && "alert")} role="progressbar" aria-valuenow={Math.round(percent)} aria-valuemin={0} aria-valuemax={100} aria-label="Progresso"><span style={{ width: `${Math.min(100, Math.max(0, percent))}%` }} /></div>;
}
function GoalSummary({ state, goal, asOf, onMove }: { state: FinanceState; goal: Goal; asOf: string; onMove: () => void }) {
  const progress = goalProgress(state, goal.id, asOf);
  return <div className="goal-summary"><span className="goal-kind">{goal.kind === "reserve" ? "Reserva de emergência" : "Objetivo pessoal"}</span><h3>{goal.name}</h3><div className="goal-amount"><strong>{formatMoney(progress.balance)}</strong><span>de {formatMoney(goal.target)}</span></div><Progress percent={progress.percent} /><div className="progress-caption"><span>{Math.round(progress.percent)}% do caminho</span><span>Faltam {formatMoney(progress.remaining)}</span></div>{goal.kind === "reserve" && <p className="fine-print">Alvo: {formatMoney(goal.essentialBase ?? 0)} de despesas essenciais × {goal.reserveMonths} meses.</p>}{goal.deadline && <p className="goal-deadline"><CalendarDays size={15} /> Prazo desejado: {dateLabel(goal.deadline)}</p>}{progress.monthlyNeeded !== null && progress.remaining > 0 && <p className="fine-print">Para alcançar o prazo: {formatMoney(progress.monthlyNeeded)}/mês. É uma referência, não uma confirmação de capacidade para aportar.</p>}<button className="button secondary" onClick={onMove} disabled={goal.archived}><Plus size={16} />{goal.archived ? "Reative para movimentar" : "Registrar movimentação"}</button><small className="caption">Posição em {dateLabel(asOf)}</small></div>;
}
function CategoryChart({ state, month }: { state: FinanceState; month: string }) {
  const metrics = monthMetrics(state, month);
  const entries = CATEGORIES.map(c => ({ ...c, value: metrics.categoryExpenses[c.id] ?? 0 })).filter(c => c.value > 0).sort((a, b) => b.value - a.value);
  const stops = entries.map((c, index) => {
    const before = entries.slice(0, index).reduce((sum, entry) => sum + entry.value, 0) / (metrics.expenses || 1) * 100;
    const after = before + c.value / (metrics.expenses || 1) * 100;
    return `${c.color} ${before}% ${after}%`;
  }).join(", ");
  if (!entries.length) return <Empty title="Seu gráfico começa nos registros." text="As despesas pagas deste mês aparecerão aqui, organizadas por categoria." />;
  return <div className="category-chart"><div className="donut" aria-hidden="true" style={{ background: `conic-gradient(${stops})` }}><div><small>Total pago</small><strong>{formatMoney(metrics.expenses)}</strong><span>{entries.length} categorias</span></div></div><div className="chart-legend">{entries.map(c => <div key={c.id}><span className="legend-dot" style={{ background: c.color }} /><span>{c.label}</span><strong>{formatMoney(c.value)}</strong></div>)}</div></div>;
}
function Comparison({ income, expenses }: { income: number; expenses: number }) {
  const max = Math.max(income, expenses, 1);
  return <section className="comparison-strip"><h3>Entradas e saídas realizadas</h3><div><span>Entradas <strong>{formatMoney(income)}</strong></span><div className="comparison-track"><i style={{ width: `${income / max * 100}%` }} /></div></div><div><span>Saídas <strong>{formatMoney(expenses)}</strong></span><div className="comparison-track muted-bar"><i style={{ width: `${expenses / max * 100}%` }} /></div></div></section>;
}
function Simulator() {
  const [result, setResult] = useState<ReturnType<typeof simulate> | null>(null);
  const [error, setError] = useState("");
  const [rate, setRate] = useState("0");
  function calculate(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const f = new FormData(e.currentTarget); setError("");
    try { setResult(simulate({ initial: parseMoney(String(f.get("initial"))), monthly: parseMoney(String(f.get("monthly"))), months: Number(f.get("months")), annualRate: String(f.get("rate")) })); }
    catch (err) { setError(err instanceof Error ? err.message : "Confira os valores informados."); setResult(null); }
  }
  const maximum = result ? Math.max(...result.rows.map(r => r.balance), 1) : 1;
  return <div className="simulator"><section className="card simulator-form"><span className="eyebrow">SIMULAÇÃO EDUCATIVA</span><h2>Tempo, aportes e possibilidades.</h2><p>Explore o efeito de guardar ao longo do tempo com uma taxa hipotética escolhida por você.</p><form onSubmit={calculate}><div className="form-grid"><Field label="Capital inicial (R$)"><input name="initial" inputMode="decimal" required defaultValue="0,00" /></Field><Field label="Aporte mensal (R$)"><input name="monthly" inputMode="decimal" required defaultValue="100,00" /></Field></div><div className="form-grid"><Field label="Prazo em meses"><input name="months" type="number" min="0" max="600" step="1" required defaultValue="12" /></Field><Field label="Taxa anual efetiva hipotética (%)"><input name="rate" inputMode="decimal" required value={rate} onChange={e => setRate(e.target.value)} /></Field></div>{rate.trim().startsWith("-") && <div className="notice warning">Uma taxa negativa representa perda de valor no cenário. Deve ser maior que −100% ao ano.</div>}{error && <div className="notice error" role="alert">{error}</div>}<button className="button primary" type="submit">Simular cenário <TrendingUp size={18} /></button></form><p className="fine-print">Aportes no fim do mês. Taxa mensal equivalente: (1 + taxa anual)^(1/12) − 1. Cálculo com precisão decimal, sem acumular arredondamentos. Os valores exibidos são arredondados para centavos, com metade para cima.</p></section><section className="card simulator-result" aria-live="polite"><span className="eyebrow">SEU CENÁRIO</span>{result ? <><div className="simulator-number"><span>Saldo projetado</span><strong>{formatMoney(result.balance)}</strong></div><dl className="number-list"><div><dt>Total aportado</dt><dd>{formatMoney(result.contributed)}</dd></div><div><dt>{result.growth < 0 ? "Perda simulada" : "Rendimento simulado"}</dt><dd className={result.growth < 0 ? "red-text" : "green-text"}>{formatMoney(result.growth)}</dd></div></dl><div className="simulator-chart" aria-label="Evolução do saldo projetado; valores na tabela abaixo">{result.rows.filter((_, i, rows) => rows.length <= 24 || i % Math.ceil(rows.length / 24) === 0 || i === rows.length - 1).map(r => <div key={r.month} title={`Mês ${r.month}: ${formatMoney(r.balance)}`}><i style={{ height: `${Math.max(1, r.balance / maximum * 100)}%` }} /><small>{r.month}</small></div>)}</div><span className="caption">Meses do cenário</span></> : <Empty title="O que muda ao longo do tempo?" text="Preencha os valores ao lado e compare o total aportado com o saldo projetado." />}<div className="notice"><Info size={17} /><span><strong>Cenário hipotético; não representa garantia de retorno.</strong><br />Impostos, custos e inflação não estão incluídos.</span></div></section>{result && <section className="card simulator-table"><h2>Evolução mês a mês</h2><div className="table-scroll"><table className="data-table"><thead><tr><th>Mês</th><th className="numeric">Total aportado</th><th className="numeric">Rendimento / perda</th><th className="numeric">Saldo projetado</th></tr></thead><tbody>{result.rows.map(row => <tr key={row.month}><td>{row.month}</td><td className="numeric">{formatMoney(row.contributed)}</td><td className="numeric">{formatMoney(row.growth)}</td><td className="numeric money">{formatMoney(row.balance)}</td></tr>)}</tbody></table></div></section>}</div>;
}



